  function mediaOptions(selected=''){return `<option value="">– vorhandenes Bild wählen –</option>${(W.data?.media||[]).map(item=>`<option value="${x(item.file_path)}" ${item.file_path===selected?'selected':''}>${x(item.seo_filename)}</option>`).join('')}`;}
  function mediaPicker(targetName,mode='single',selected=''){return `<div class="v218-media-picker"><select data-v218-media-select data-target-name="${x(targetName)}" data-mode="${x(mode)}">${mediaOptions(selected)}</select><small>Oder ein bereits optimiertes Bild aus der Medienbibliothek einsetzen.</small></div>`;}
  function blockTranslationPanels(block){return Object.keys(W.data.languages).map(code=>{const c=contentFor(block,code);const items=(c.items||[]).map(i=>`${i.icon||'✓'}|${i.title||''}|${i.text||''}`).join('\n');return `<section class="v218-language-panel ${code===W.language?'active':''}" data-v218-lang-panel="block-${code}"><div data-v218-content-for="hero booking_search type_grid rich_text image_text features icon_cards split_cards cta_banner price_notice seasonal_notice availability_teaser trust_badges stats timeline tabs faq accordion contact map team gallery reviews download_links video_embed custom_html custom_form"><div class="form-grid two"><div class="field span-2"><label>Überschrift</label><input name="bc_${code}_title" value="${x(c.title||'')}"></div><div class="field span-2"><label>Unterzeile</label><textarea name="bc_${code}_subtitle" rows="2">${x(c.subtitle||'')}</textarea></div></div></div><div data-v218-content-for="hero booking_search type_grid rich_text image_text features icon_cards split_cards cta_banner price_notice seasonal_notice availability_teaser trust_badges stats timeline tabs faq accordion contact map team gallery reviews download_links video_embed custom_html custom_form"><div class="form-grid two"><div class="field"><label>Button-Text</label><input name="bc_${code}_button_label" value="${x(c.button_label||'')}"></div><div class="field"><label>Button-Link</label><input name="bc_${code}_button_url" value="${x(c.button_url||'')}"></div></div></div><div data-v218-content-for="hero image_text gallery cta_banner video_embed"><div class="field"><label>Bild-Alternativtext</label><input name="bc_${code}_image_alt" value="${x(c.image_alt||'')}"></div></div><div data-v218-content-for="hero rich_text image_text contact map gallery reviews custom_html custom_form cta_banner price_notice seasonal_notice availability_teaser video_embed"><div class="field v218-rich-wrap"><label>Editor mit Vollausstattung</label><small>Texte, Icons, Emojis, Tabellen, Bilder, Hinweisboxen und Links direkt im Abschnitt pflegen.</small>${richToolbar(`v218-rich-${code}`)}<div class="v218-rich-editor" id="v218-rich-${code}" contenteditable="true">${c.content_html||''}</div></div></div><div data-v218-content-for="features icon_cards split_cards trust_badges stats timeline tabs faq accordion reviews team download_links"><div class="field" data-v218-items-wrap><label>Einträge / Bewertungen</label><textarea name="bc_${code}_items" rows="10" placeholder="Bewertungen: Sterne|Name|Text|Herkunft|Zeitraum – z. B. 5|Familie Müller|Sehr schöner Aufenthalt.|Deutschland|Juli 2026">${x(items)}</textarea><small>Für Bewertungen: Sterne|Name|Text|Herkunft|Zeitraum. Für FAQ/Vorteile: Icon|Überschrift|Text.</small></div></div></section>`}).join('');}
  function richToolbar(target){return `<div class="v218-rich-tools v23669-rich-tools" data-target="${target}">
    <div class="v23669-rich-head"><b>Großzügiger WYSIWYG-Editor</b><small>Texte, Emojis, Ausstattung, Grafiken, Karten-/Anfahrtsboxen, Tabellen und CTA-Bereiche direkt einfügen.</small></div>
    <div class="v218-rich-row"><button type="button" data-v218-rich="formatBlock" data-value="p">Absatz</button><button type="button" data-v218-rich="formatBlock" data-value="h1">H1</button><button type="button" data-v218-rich="formatBlock" data-value="h2">H2</button><button type="button" data-v218-rich="formatBlock" data-value="h3">H3</button><button type="button" data-v218-rich="formatBlock" data-value="h4">H4</button><button type="button" data-v218-rich="formatBlock" data-value="blockquote">Zitat</button><button type="button" data-v218-rich="insertHorizontalRule">Linie</button></div>
    <div class="v218-rich-row"><button type="button" data-v218-rich="bold"><b>B</b></button><button type="button" data-v218-rich="italic"><i>I</i></button><button type="button" data-v218-rich="underline"><u>U</u></button><button type="button" data-v218-rich="insertUnorderedList">Liste</button><button type="button" data-v218-rich="insertOrderedList">1. Liste</button><button type="button" data-v218-rich="createLink">Link</button><button type="button" data-v218-rich="removeFormat">Format löschen</button></div>
    <div class="v218-rich-row"><button type="button" data-v218-rich-special="table">Tabelle</button><button type="button" data-v218-rich-special="image">Bild</button><button type="button" data-v218-rich-special="notice">Hinweisbox</button><button type="button" data-v218-template="cta">CTA</button><button type="button" data-v218-template="twocol">2 Spalten</button><button type="button" data-v218-template="cards">Grafik-Karten</button><button type="button" data-v218-template="amenities">Ausstattung</button><button type="button" data-v218-template="route">Anfahrt/OSM</button><button type="button" data-v218-template="quote">Zitat</button><button type="button" data-v218-template="checklist">Checkliste</button></div>
    <div class="v218-rich-row v23669-template-row"><details class="v218-rich-palette" open><summary>Ausstattungs-Icons</summary><div>${richIconsV236.map(icon=>`<button type="button" data-v218-insert-html="<span>${x(icon)}</span> ">${x(icon)}</button>`).join('')}</div></details><details class="v218-rich-palette"><summary>Emojis</summary><div>${richEmojiV236.map(icon=>`<button type="button" data-v218-insert-html="<span>${x(icon)}</span> ">${x(icon)}</button>`).join('')}</div></details><details class="v218-rich-palette"><summary>Vorlagen</summary><div><button type="button" data-v218-template="galleryhint">Galerie-Hinweis</button><button type="button" data-v218-template="cards">Kacheln</button><button type="button" data-v218-template="route">Anfahrt</button><button type="button" data-v218-template="cta">Buchungsaufruf</button></div></details></div>
  </div>`;}
  function blockSettings(block){const s=block.settings||{},chosen=s.image_url||s.background_image||'';return `<div class="v218-block-settings"><h3>Darstellung</h3><div data-v218-setting-for="hero booking_search type_grid rich_text image_text features icon_cards split_cards cta_banner price_notice seasonal_notice availability_teaser trust_badges stats timeline tabs faq accordion contact map team gallery reviews download_links video_embed custom_html custom_form spacer"><div class="form-grid two"><div class="field"><label>Block-Stil</label><select name="setting_variant"><option value="default" ${s.variant==='default'||!s.variant?'selected':''}>Standard</option><option value="soft" ${s.variant==='soft'?'selected':''}>Weich / hell</option><option value="premium" ${s.variant==='premium'?'selected':''}>Premium dunkel</option><option value="accent" ${s.variant==='accent'?'selected':''}>Akzentfläche</option></select></div><div class="field"><label>Karten pro Reihe</label><select name="setting_columns"><option value="0" ${Number(s.columns||0)===0?'selected':''}>Automatisch</option><option value="2" ${Number(s.columns||0)===2?'selected':''}>2</option><option value="3" ${Number(s.columns||0)===3?'selected':''}>3</option><option value="4" ${Number(s.columns||0)===4?'selected':''}>4</option></select></div><div class="field"><label>Abschnitt-Hintergrund</label><input type="color" name="setting_section_bg" value="${x(s.section_bg||'#ffffff')}"></div><div class="field"><label>Textfarbe</label><input type="color" name="setting_section_text" value="${x(s.section_text||'#172033')}"></div><label class="info-box span-2"><input type="checkbox" name="setting_full_width" value="1" ${Number(s.full_width||0)?'checked':''}> Abschnitt breit/großzügig darstellen</label></div></div><div data-v218-setting-for="hero image_text"><div class="field"><label>Bild</label><input name="setting_image_url" value="${x(chosen)}">${mediaPicker('setting_image_url','single',chosen)}<div class="v218-upload-row"><input type="file" accept="image/jpeg,image/png,image/webp" data-v218-upload="single" data-target-name="setting_image_url"><small>Neues JPG, PNG oder WebP automatisch optimieren</small></div></div></div><div data-v218-setting-for="hero"><div class="form-grid two"><div class="field"><label>Textausrichtung</label><select name="setting_alignment"><option value="left" ${s.alignment==='left'?'selected':''}>Links</option><option value="center" ${s.alignment==='center'?'selected':''}>Zentriert</option><option value="right" ${s.alignment==='right'?'selected':''}>Rechts</option></select></div><div class="field"><label>Bereichshöhe</label><select name="setting_height"><option value="small" ${s.height==='small'?'selected':''}>Klein</option><option value="medium" ${s.height==='medium'?'selected':''}>Mittel</option><option value="large" ${s.height==='large'?'selected':''}>Groß</option></select></div></div></div><div data-v218-setting-for="image_text"><div class="field"><label>Bildposition</label><select name="setting_image_position"><option value="right" ${s.image_position==='right'?'selected':''}>Rechts</option><option value="left" ${s.image_position==='left'?'selected':''}>Links</option></select></div></div><div data-v218-setting-for="custom_form"><div class="field"><label>Angezeigtes Formular</label><select name="setting_form_index"><option value="1" ${Number(s.form_index||1)===1?'selected':''}>Formular 1</option><option value="2" ${Number(s.form_index||1)===2?'selected':''}>Formular 2</option><option value="3" ${Number(s.form_index||1)===3?'selected':''}>Formular 3</option></select><small>Die Formulare werden unter Design & Formulartexte gepflegt.</small></div></div><div data-v218-setting-for="type_grid reviews icon_cards split_cards trust_badges stats timeline tabs faq accordion team download_links"><div class="form-grid two"><div class="field"><label>Anzahl anzeigen</label><input type="number" min="0" max="50" name="setting_limit" value="${Number(s.limit||0)}"><small>0 zeigt alle Einträge.</small></div><label class="info-box"><input type="checkbox" name="setting_show_description" value="1" ${Number(s.show_description??1)?'checked':''}> Beschreibung anzeigen</label><label class="info-box"><input type="checkbox" name="setting_show_amenities" value="1" ${Number(s.show_amenities??1)?'checked':''}> Ausstattung anzeigen</label></div></div><div data-v218-setting-for="spacer"><div class="form-grid two"><div class="field"><label>Abstand in Pixel</label><input type="number" min="10" max="240" name="setting_spacer_height" value="${Number.isFinite(Number(s.height))?Number(s.height):40}"></div><label class="info-box"><input type="checkbox" name="setting_line" value="1" ${Number(s.line||0)?'checked':''}> Trennlinie anzeigen</label></div></div><div data-v218-setting-for="gallery video_embed download_links"><div class="field"><label>Galeriebilder – eine Bildadresse pro Zeile</label><textarea name="setting_images" rows="6">${x((s.images||[]).join('\n'))}</textarea>${mediaPicker('setting_images','multiple','')}<div class="v218-upload-row"><input type="file" multiple accept="image/jpeg,image/png,image/webp" data-v218-upload="multiple" data-target-name="setting_images"><small>Mehrere Bilder auswählen; optimierte Adressen werden automatisch ergänzt.</small></div></div></div><div data-v218-setting-for="booking_search rich_text features faq reviews custom_html contact custom_form"><div class="v218-help-box compact"><b>Gestaltung über Text und Button</b><span>Überschrift, Text und optionaler Button werden in den Sprachreitern gepflegt.</span></div></div><div data-v218-setting-for="hero booking_search type_grid rich_text image_text features icon_cards split_cards cta_banner price_notice seasonal_notice availability_teaser trust_badges stats timeline tabs faq accordion contact map team gallery reviews download_links video_embed custom_html custom_form"><h3>Block-Button</h3><div class="form-grid two"><div class="field"><label>Button-Farbe</label><input type="color" name="setting_button_bg" value="${x(s.button_bg||'#2563eb')}"></div><div class="field"><label>Button-Textfarbe</label><input type="color" name="setting_button_text" value="${x(s.button_text||'#ffffff')}"></div><div class="field"><label>Button-Größe</label><select name="setting_button_size"><option value="small" ${s.button_size==='small'?'selected':''}>Klein</option><option value="normal" ${(s.button_size||'normal')==='normal'?'selected':''}>Normal</option><option value="large" ${s.button_size==='large'?'selected':''}>Groß</option></select></div><div class="field"><label>Button-Rundung</label><input type="number" min="0" max="40" name="setting_button_radius" value="${Number(s.button_radius??18)}"></div><div class="field"><label>Ausrichtung</label><select name="setting_button_align"><option value="left" ${(s.button_align||'left')==='left'?'selected':''}>Links</option><option value="center" ${s.button_align==='center'?'selected':''}>Zentriert</option><option value="right" ${s.button_align==='right'?'selected':''}>Rechts</option></select></div></div></div></div>`;}
  function toggleBlockEditor(form){const type=form?.elements?.block_type?.value||form?.dataset?.blockType||'rich_text';form?.querySelectorAll('[data-v218-setting-for],[data-v218-content-for]').forEach(el=>{const types=String(el.dataset.v218SettingFor||el.dataset.v218ContentFor||'').split(/\s+/);el.hidden=!types.includes(type);});}
  function openBlockEditor(block=null){const p=page();block=block||{id:0,page_id:p.id,block_type:'rich_text',active:1,locked:0,sort_order:(p.blocks.length+1)*10,settings:{},translations:{}};const body=`<form id="v218BlockForm" data-v218-form="block"><input type="hidden" name="id" value="${Number(block.id||0)}"><input type="hidden" name="page_id" value="${p.id}"><div class="v218-help-box"><b>Seitenabschnitt</b><span>Geschützte Funktionsblöcke wie die Buchungssuche können gestaltet und verschoben, aber nicht technisch gelöscht werden.</span></div><div class="form-grid two"><div class="field"><label>Blocktyp</label><select name="block_type" ${Number(block.locked)?'disabled':''}>${Object.entries(W.data.block_types).map(([key,label])=>`<option value="${key}" ${key===block.block_type?'selected':''}>${x(label)}</option>`).join('')}</select></div><div class="field"><label>Sortierung</label><input type="number" name="sort_order" value="${Number(block.sort_order||0)}"></div><label class="info-box span-2"><input type="checkbox" name="active" value="1" ${Number(block.active)?'checked':''}> Block öffentlich anzeigen</label></div>${blockSettings(block)}<h3>Inhalte in allen Sprachen</h3>${languageTabs(W.language,'block')}${blockTranslationPanels(block)}</form>`;modal(block.id?'Abschnitt bearbeiten':'Neuen Abschnitt anlegen',body,`<button class="btn" type="button" data-close-modal>Abbrechen</button><button class="btn primary" type="submit" form="v218BlockForm">Abschnitt speichern</button>`,true);const form=document.getElementById('v218BlockForm');if(form){form.dataset.blockType=block.block_type;toggleBlockEditor(form);setTimeout(()=>enhanceBlockTypeSelectV23684(document),0);}}
  function colorInput(key,label,d){
    const raw=String(d[key]||'').trim();
    const val=/^#[0-9a-f]{6}$/i.test(raw)?raw:'#2563eb';
    return `<div class="field v23684-color-field" data-v23684-color-field><label>${label}</label><div class="v23684-color-control"><input type="color" name="${key}" value="${x(val)}" data-v23684-color="${key}"><input type="text" value="${x(val)}" maxlength="7" data-v23684-color-text="${key}" spellcheck="false"><span class="v23684-color-swatch" style="background:${x(val)}"></span></div></div>`;
  }
  function designPreview(d){return `<aside class="v236-design-preview" data-v236-design-preview><div class="v236-preview-head" style="background:${x(d.header_background||'#101827')};color:${x(d.header_text||'#ffffff')}"><b>${x((W.data?.pages?.[0]?.display_title)||'StayPilot')}</b><span>Menü</span></div><div class="v236-preview-search" style="background:${x(d.booking_search_background||'#ffffff')}"><h4 style="color:${x(d.booking_search_heading||'#172033')}">Buchungssuche</h4><div class="v236-preview-search-panel" style="background:${x(d.booking_search_surface||'#ffffff')};color:${x(d.booking_search_text||'#172033')};border-radius:${Number(d.booking_search_radius||18)}px"><span>Anreise</span><span>Abreise</span><button type="button" style="background:${x(d.booking_search_button_bg||'#2563eb')};color:${x(d.booking_search_button_text||'#ffffff')}">Prüfen</button></div></div><div class="v236-preview-footer" style="background:${x(d.footer_background||'#101827')};color:${x(d.footer_text||'#dbe5f3')}"><b style="color:${x(d.footer_heading||'#ffffff')}">Footer</b><span style="color:${x(d.footer_link||'#dbe5f3')}">Navigation · Kontakt</span></div></aside>`;}
  function designFields(d){return `<div class="v236-design-layout"><section class="v236-panel"><h3>Basisdesign</h3><div class="v23684-preset-row"><button type="button" data-v23684-design-preset="costa">🌊 Costa Brava hell</button><button type="button" data-v23684-design-preset="premium">✨ Premium dunkel</button><button type="button" data-v23684-design-preset="nature">🌿 Natur grün</button><button type="button" data-v23684-design-preset="modern">💎 Modern blau</button></div><div class="v23684-design-preview"><b>Live-Farbvorschau</b><span>Änderungen an Farben werden sofort als Farbfeld sichtbar.</span><div><i style="background:var(--sp-prev-primary,#2563eb)"></i><i style="background:var(--sp-prev-secondary,#0f766e)"></i><i style="background:var(--sp-prev-header,#0f172a)"></i><i style="background:var(--sp-prev-bg,#f4f7fb)"></i></div></div><div class="form-grid two"><div class="field"><label>Logo</label><input name="logo_url" value="${x(d.logo_url||'')}">${mediaPicker('logo_url','single',d.logo_url||'')}<div class="v218-upload-row"><input type="file" accept="image/jpeg,image/png,image/webp" data-v218-upload="single" data-target-name="logo_url"><small>Automatisch optimieren</small></div></div><div class="field"><label>Favicon</label><input name="favicon_url" value="${x(d.favicon_url||'')}">${mediaPicker('favicon_url','single',d.favicon_url||'')}<div class="v218-upload-row"><input type="file" accept="image/jpeg,image/png,image/webp" data-v218-upload="single" data-target-name="favicon_url"><small>Quadratisches Bild empfohlen.</small></div></div>${['primary|Hauptfarbe','secondary|Akzentfarbe','background|Seitenhintergrund','surface|Flächenfarbe','text|Textfarbe','muted|Dezente Textfarbe','header_background|Header-Hintergrund','header_text|Header-Text'].map(row=>{const [key,label]=row.split('|');return colorInput(key,label,d)}).join('')}<div class="field"><label>Schrift</label><select name="font"><option value="system" ${d.font==='system'?'selected':''}>Systemschrift</option><option value="modern" ${d.font==='modern'?'selected':''}>Modern</option><option value="serif" ${d.font==='serif'?'selected':''}>Klassisch</option></select></div><div class="field"><label>Inhaltsbreite</label><input type="number" min="760" max="1600" name="content_width" value="${Number(d.content_width||1180)}"></div><div class="field"><label>Eckenradius</label><input type="number" min="0" max="40" name="radius" value="${Number(d.radius||18)}"></div><div class="field"><label>Button-Form</label><select name="button_style"><option value="rounded" ${d.button_style==='rounded'?'selected':''}>Abgerundet</option><option value="pill" ${d.button_style==='pill'?'selected':''}>Pill</option><option value="square" ${d.button_style==='square'?'selected':''}>Eckig</option></select></div><label class="info-box"><input type="checkbox" name="sticky_header" value="1" ${Number(d.sticky_header)?'checked':''}> Kopfzeile bleibt sichtbar</label><label class="info-box"><input type="checkbox" name="card_shadow" value="1" ${Number(d.card_shadow)?'checked':''}> Schatten an Karten</label><label class="info-box"><input type="checkbox" name="show_admin_link" value="1" ${Number(d.show_admin_link)?'checked':''}> Verwaltungslink öffentlich zeigen</label></div><h3>Buchungssuche</h3><div class="form-grid two">${['booking_search_background|Bereichsfarbe','booking_search_surface|Formularfläche','booking_search_text|Textfarbe','booking_search_heading|Überschriften','booking_search_button_bg|Button-Farbe','booking_search_button_text|Button-Text'].map(row=>{const [key,label]=row.split('|');return colorInput(key,label,d)}).join('')}<div class="field"><label>Rundung Buchungssuche</label><input type="number" min="0" max="40" name="booking_search_radius" value="${Number(d.booking_search_radius||18)}"></div><label class="info-box"><input type="checkbox" name="booking_search_shadow" value="1" ${Number(d.booking_search_shadow??1)?'checked':''}> Schatten an Buchungssuche</label></div><h3>Wohnungstypen</h3><div class="form-grid two"><div class="field"><label>Wohnungstyp-Kacheln</label><select name="type_card_layout"><option value="portrait" ${(d.type_card_layout||'portrait')==='portrait'?'selected':''}>Hochformat-Kacheln / Smartphone stark</option><option value="wide" ${d.type_card_layout==='wide'?'selected':''}>Breite Karten</option><option value="compact" ${d.type_card_layout==='compact'?'selected':''}>Kompakt</option></select><small>Mehrere Bilder pro Typ werden automatisch als Slider gezeigt.</small></div><div class="field"><label>Typ-Detailgalerie</label><select name="type_detail_gallery_layout"><option value="magazine" ${(d.type_detail_gallery_layout||'magazine')==='magazine'?'selected':''}>Großzügig / Magazin</option><option value="classic" ${d.type_detail_gallery_layout==='classic'?'selected':''}>Klassisch</option></select></div><div class="field"><label>Slider-Intervall ms</label><input type="number" min="0" max="12000" step="100" name="type_slider_interval" value="${Number(d.type_slider_interval||4200)}"><small>0 = keine automatische Bewegung.</small></div></div></section>${designPreview(d)}</div>`;}
  function contactFields(d){return `<div class="v236-design-layout"><section class="v236-panel"><h3>Kontakt</h3><div class="form-grid two"><div class="field"><label>Telefon</label><input name="phone" value="${x(d.phone||'')}"></div><div class="field"><label>Öffentliche E-Mail</label><input type="email" name="email" value="${x(d.email||'')}"></div><div class="field span-2"><label>Adresse</label><textarea name="address" rows="4">${x(d.address||'')}</textarea></div>${['contact_background|Kontakt-Hintergrund','contact_text|Kontakt-Text','contact_accent|Kontakt-Akzent'].map(row=>{const [key,label]=row.split('|');return colorInput(key,label,d)}).join('')}<div class="field"><label>Facebook-Adresse</label><input name="facebook_url" value="${x(d.facebook_url||'')}"></div><div class="field"><label>Instagram-Adresse</label><input name="instagram_url" value="${x(d.instagram_url||'')}"></div><div class="field span-2"><label>Copyright-Zeile</label><input name="copyright" value="${x(d.copyright||'')}"></div></div><h3>OpenStreetMap / Anfahrt</h3><div class="v23669-osm-note"><b>🗺️ OSM-Karte</b><span>Koordinaten eintragen und optional den direkten Routenlink von OpenStreetMap hinterlegen. Der Kontaktblock zeigt die Karte im Frontend.</span></div><div class="form-grid two"><label class="info-box span-2"><input type="checkbox" name="contact_map_enabled" value="1" ${Number(d.contact_map_enabled)?'checked':''}> Karte im Kontaktbereich anzeigen</label><div class="field"><label>Breitengrad</label><input name="contact_map_lat" value="${x(d.contact_map_lat||'')}" placeholder="z. B. 39.568"></div><div class="field"><label>Längengrad</label><input name="contact_map_lng" value="${x(d.contact_map_lng||'')}" placeholder="z. B. 2.650"></div><div class="field"><label>Zoom</label><input type="number" min="1" max="19" name="contact_map_zoom" value="${Number(d.contact_map_zoom||15)}"></div><div class="field"><label>Kartenhöhe</label><input type="number" min="180" max="640" name="contact_map_height" value="${Number(d.contact_map_height||320)}"></div><div class="field span-2"><label>OSM-Link</label><input name="contact_map_link" value="${x(d.contact_map_link||'')}" placeholder="https://www.openstreetmap.org/..."></div></div></section><section class="v236-panel"><h3>Footer</h3><div class="form-grid two">${['footer_background|Footer-Hintergrund','footer_text|Footer-Text','footer_heading|Footer-Überschriften','footer_link|Footer-Links'].map(row=>{const [key,label]=row.split('|');return colorInput(key,label,d)}).join('')}<div class="field"><label>Footer-Spalten</label><select name="footer_columns"><option value="1" ${Number(d.footer_columns||3)===1?'selected':''}>1 Spalte</option><option value="2" ${Number(d.footer_columns||3)===2?'selected':''}>2 Spalten</option><option value="3" ${Number(d.footer_columns||3)===3?'selected':''}>3 Spalten</option></select></div></div><div class="v236-map-preview"><b>Karten-Vorschau</b><span>Koordinaten eintragen, speichern und in der öffentlichen Vorschau prüfen.</span></div></section></div>`;}
  function labelPanel(code){const labels=W.data.labels[code]||{};return `<section class="v218-language-panel ${code===W.language?'active':''}" data-v218-lang-panel="labels-${code}"><div class="v218-label-grid">${Object.entries(labelNames).map(([key,label])=>`<div class="field"><label>${x(label)}</label>${String(labels[key]||'').length>100?`<textarea name="label_${code}_${key}" rows="3">${x(labels[key]||'')}</textarea>`:`<input name="label_${code}_${key}" value="${x(labels[key]||'')}">`}</div>`).join('')}</div></section>`;}
  function cookieFields(d){return `<div class="v236-design-layout"><section class="v236-panel"><h3>Cookie Einwilligung</h3><div class="form-grid two"><label class="info-box span-2"><input type="checkbox" name="cookie_enabled" value="1" ${Number(d.cookie_enabled??1)?'checked':''}> Zustimmungsdialog aktivieren</label><div class="field"><label>Position</label><select name="cookie_position"><option value="bottom" ${(d.cookie_position||'bottom')==='bottom'?'selected':''}>Unten</option><option value="top" ${d.cookie_position==='top'?'selected':''}>Oben</option></select></div><div class="field"><label>Randabstand</label><input type="number" min="0" max="80" name="cookie_margin" value="${Number(d.cookie_margin??18)}"></div><div class="field"><label>Innenabstand</label><input type="number" min="8" max="60" name="cookie_padding" value="${Number(d.cookie_padding??18)}"></div><div class="field"><label>Runde Ecken</label><input type="number" min="0" max="40" name="cookie_radius" value="${Number(d.cookie_radius??18)}"></div>${['cookie_background|Hintergrundfarbe','cookie_text|Textfarbe','cookie_accent|Akzentfarbe'].map(row=>{const [key,label]=row.split('|');return colorInput(key,label,d)}).join('')}<div class="field span-2"><label>Hinweistext</label><textarea name="cookie_notice" rows="4">${x(d.cookie_notice||'')}</textarea></div><div class="field span-2"><label>Text wenn Inhalt deaktiviert ist</label><textarea name="cookie_blocked_text" rows="3">${x(d.cookie_blocked_text||'')}</textarea></div></div></section><section class="v236-panel"><h3>Cookies & Dienste</h3><div class="field"><label>Diensteliste</label><textarea name="cookie_services" rows="14" class="v236-code-textarea" placeholder="Name|Kategorie|Cookie-Namen|Beschreibung|Aktiv">${x(d.cookie_services||'')}</textarea><small>Eine Zeile je Dienst. Kategorien: necessary, preferences, statistics, marketing. Cookie-Namen mit Komma trennen. Aktiv: 1 oder 0. Sichtbare Cookies werden im Gastmodus zusätzlich automatisch erkannt.</small></div><div class="v236-cookie-example"><b>Beispiel</b><span>Google Analytics|statistics|_ga,_gid|Anonyme Statistik|0</span></div></section></div>`;}
  function parseFormFieldRowsV23684(value){
    const rows=String(value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);
    return (rows.length?rows:['Name|text|1|Ihr Name','E-Mail|email|1|Ihre E-Mail-Adresse','Nachricht|textarea|1|Ihre Nachricht']).map((line,index)=>{
      const parts=line.split('|');
      return {label:(parts[0]||'Feld '+(index+1)).trim(),type:(parts[1]||'text').trim(),required:String(parts[2]??'0').trim()==='1',placeholder:(parts[3]||'').trim(),options:(parts[4]||'').trim(),help:(parts[5]||'').trim()};
    });
  }
  function formFieldRowV23684(formIndex,field,index){
    const types={text:'Text',email:'E-Mail',tel:'Telefon',date:'Datum',number:'Zahl',textarea:'Textbereich',select:'Auswahl',checkbox:'Checkbox'};
    return `<article class="v23684-form-field" data-v23684-form-field="${formIndex}">
      <div class="v23684-form-field-head"><b>Feld ${index+1}</b><div><button type="button" class="btn small" data-v23684-field-action="up">↑</button><button type="button" class="btn small" data-v23684-field-action="down">↓</button><button type="button" class="btn small" data-v23684-field-action="copy">Kopieren</button><button type="button" class="btn small danger" data-v23684-field-action="delete">Löschen</button></div></div>
      <div class="form-grid two">
        <div class="field"><label>Feldname</label><input data-v23684-form-part="label" value="${x(field.label)}" placeholder="z. B. Telefon"></div>
        <div class="field"><label>Feldtyp</label><select data-v23684-form-part="type">${Object.entries(types).map(([key,label])=>`<option value="${key}" ${field.type===key?'selected':''}>${label}</option>`).join('')}</select></div>
        <label class="info-box"><input type="checkbox" data-v23684-form-part="required" ${field.required?'checked':''}> Pflichtfeld</label>
        <div class="field"><label>Platzhalter</label><input data-v23684-form-part="placeholder" value="${x(field.placeholder)}" placeholder="z. B. Ihre Telefonnummer"></div>
        <div class="field"><label>Auswahloptionen</label><input data-v23684-form-part="options" value="${x(field.options)}" placeholder="nur bei Auswahl: Option 1, Option 2"></div>
        <div class="field"><label>Hilfetext</label><input data-v23684-form-part="help" value="${x(field.help)}" placeholder="kleiner Hinweis unter dem Feld"></div>
      </div>
    </article>`;
  }
  function customFormsPanel(d){
    const forms=Array.isArray(d.custom_forms)?d.custom_forms:[];
    return `<div class="v23684-builder-head"><div><b>Moderner Formular-Builder</b><span>Keine technischen Zeilen mehr: Felder, Pflichtangaben, Platzhalter und Hilfetexte werden als Karten gepflegt.</span></div><div class="v236-form-builder-kpis"><span>3 Formulare</span><span>Platzhalter sichtbar</span><span>Felder kopieren</span></div></div>
      <div class="v236-custom-forms v23684-custom-forms">${[0,1,2].map(i=>{const f=forms[i]||{};const fields=parseFormFieldRowsV23684(f.fields||'');return `<section class="v236-panel v23684-form-panel" data-v23684-form-panel="${i}">
        <div class="v23684-panel-title"><h3>Formular ${i+1}</h3><button type="button" class="btn small primary" data-v23684-add-field="${i}">+ Feld hinzufügen</button></div>
        <div class="form-grid two">
          <label class="info-box span-2"><input type="checkbox" name="custom_form_${i}_active" value="1" ${Number(f.active)?'checked':''}> Formular aktiv</label>
          <div class="field"><label>Name</label><input name="custom_form_${i}_name" value="${x(f.name||('Formular '+(i+1)))}"></div>
          <div class="field"><label>Empfänger-E-Mail</label><input type="email" name="custom_form_${i}_recipient" value="${x(f.recipient||'')}" placeholder="leer = öffentliche E-Mail"></div>
          <div class="field span-2"><label>Erfolgsmeldung</label><input name="custom_form_${i}_success" value="${x(f.success||'Vielen Dank. Ihre Nachricht wurde gesendet.')}" placeholder="Text nach dem Absenden"></div>
        </div>
        <input type="hidden" name="custom_form_${i}_fields" data-v23684-form-storage="${i}" value="${x(f.fields||'')}">
        <div class="v23684-form-fields" data-v23684-form-fields="${i}">${fields.map((field,index)=>formFieldRowV23684(i,field,index)).join('')}</div>
        <div class="v23684-form-preview" data-v23684-form-preview="${i}"></div>
      </section>`}).join('')}</div>
      <h3>Buchungssuche-Texte</h3>${languageTabs(W.language,'labels')}<div class="v236-form-builder-grid">${Object.keys(W.data.languages).map(labelPanel).join('')}</div>`;
  }
  function inquirySettingsPanel(d){
    const bool=(key,label,help='')=>`<label class="info-box"><input type="checkbox" name="${key}" value="1" ${Number(d[key])?'checked':''}> <b>${x(label)}</b>${help?`<small>${x(help)}</small>`:''}</label>`;
    return `<div class="v236-form-builder-head"><div><b>Preisanfrage / Anfrageformular</b><span>Hier steuern Sie das Formular, das nach Klick auf „Unverbindlich anfragen“ erscheint. Alle Textbausteine darunter sind mehrsprachig.</span></div><div class="v236-form-builder-kpis"><span>Modal-Formular</span><span>Optionale Felder</span><span>Mehrsprachig</span></div></div><div class="v236-custom-forms"><section class="v236-panel"><h3>Sichtbarkeit & Pflichtfelder</h3><div class="form-grid two">${bool('inquiry_show_summary','Zusammenfassung oben anzeigen','Wohnungstyp, Zeitraum und Preis im Modal zeigen.')}${bool('inquiry_show_top_notice','Infotext oben anzeigen','Der Unverbindlichkeits-Hinweis oberhalb der Felder.')}${bool('inquiry_phone_required','Telefon als Pflichtfeld')}${bool('inquiry_country_required','Land als Pflichtfeld')}${bool('inquiry_privacy_required','Datenschutz-Bestätigung als Pflichtfeld')}${bool('inquiry_marketing_consent','Optionale Marketing-Zustimmung anzeigen')}</div></section><section class="v236-panel"><h3>Zusatzoptionen im Formular</h3><div class="form-grid two">${bool('inquiry_show_breakfast','Frühstück-Option anzeigen')}${bool('inquiry_show_half_board','Halbpension-Option anzeigen')}${bool('inquiry_show_contact_preference','Bevorzugten Kontakt anzeigen')}${bool('inquiry_show_arrival_time','Voraussichtliche Anreisezeit anzeigen')}${bool('inquiry_show_location_request','Lagewunsch anzeigen')}${bool('inquiry_show_special_occasion','Besonderen Anlass / Hinweis anzeigen')}</div></section></div><h3>Texte der Preisanfrage</h3><div class="v218-help-box"><b>Hinweis</b><span>Diese Texte erscheinen direkt im Anfrage-Popup: Überschrift, Infotext, Platzhalter, Datenschutz, Button und Erfolgsmeldung.</span></div>${languageTabs(W.language,'labels')}<div class="v236-form-builder-grid">${Object.keys(W.data.languages).map(labelPanel).join('')}</div>`;
  }

  function openDesignEditor(){const d=W.data.design;const body=`<form id="v218DesignForm" data-v218-form="design"><div class="v218-editor-tabs"><button type="button" class="active" data-v218-design-tab="design">Design</button><button type="button" data-v218-design-tab="inquiry">Preisanfrage</button><button type="button" data-v218-design-tab="contact">Kontakt & Footer</button><button type="button" data-v218-design-tab="cookies">Cookie-Center</button><button type="button" data-v218-design-tab="labels">Formular-Builder</button></div><section data-v218-design-panel="design">${designFields(d)}</section><section data-v218-design-panel="inquiry" hidden>${inquirySettingsPanel(d)}</section><section data-v218-design-panel="contact" hidden>${contactFields(d)}</section><section data-v218-design-panel="cookies" hidden>${cookieFields(d)}</section><section data-v218-design-panel="labels" hidden>${customFormsPanel(d)}</section></form>`;modal('Website-Studio: Design, Preisanfrage und Formulare',body,`<button class="btn" type="button" data-close-modal>Abbrechen</button><button class="btn primary" type="submit" form="v218DesignForm">Einstellungen speichern</button>`,true);setTimeout(()=>{syncColorControlsV23684(document);syncAllFormBuildersV23684(document);enhanceBlockTypeSelectV23684(document);},0);} 

  function openMediaLibrary(){const media=W.data?.media||[];const cards=media.map(item=>`<article class="v218-media-card"><img src="../${x(item.thumb_path||item.file_path)}" alt=""><div><b>${x(item.seo_filename)}</b><small>${Number(item.width||0)} × ${Number(item.height||0)} · ${Math.max(1,Math.round(Number(item.size_bytes||0)/1024))} KB</small></div><div class="toolbar"><button class="btn small" type="button" data-v218-action="copy-media" data-path="${x(item.file_path)}">Pfad kopieren</button><button class="btn small" type="button" data-v218-action="edit-media" data-id="${item.id}">Bildtexte</button><button class="btn small danger" type="button" data-v218-action="delete-media" data-id="${item.id}">Löschen</button></div></article>`).join('')||'<div class="empty">Noch keine Webseitenbilder vorhanden.</div>';const body=`<div class="v218-help-box"><b>Zentrale Webseiten-Medien</b><span>Neue Bilder werden automatisch verkleinert, als WebP gespeichert und erhalten ein Vorschaubild. Bereits verwendete Bilder können nicht gelöscht werden.</span></div><div class="v218-library-upload"><label class="btn primary">＋ Bilder hochladen<input type="file" multiple hidden accept="image/jpeg,image/png,image/webp" data-v218-upload="library"></label><small>Maximal 12 MB je Bild · PHP-GD/WebP erforderlich</small></div><div class="v218-media-grid">${cards}</div>`;modal('Medienbibliothek',body,`<button class="btn" type="button" data-close-modal>Schließen</button>`,true);}
  function openMediaMeta(item){const body=`<form id="v218MediaMetaForm" data-v218-form="media-meta"><input type="hidden" name="id" value="${Number(item.id)}"><div class="v218-media-meta-preview"><img src="../${x(item.thumb_path||item.file_path)}" alt=""><div><b>${x(item.seo_filename)}</b><small>Alternative Bildtexte beschreiben den Bildinhalt für Suchmaschinen und Screenreader.</small></div></div><div class="form-grid two">${Object.entries(W.data.languages).map(([code,name])=>`<div class="field"><label>${x(name)}</label><input name="alt_${code}" maxlength="255" value="${x(item.alt_texts?.[code]||'')}"></div>`).join('')}</div></form>`;modal('Mehrsprachige Bildtexte',body,`<button class="btn" type="button" data-v218-action="media">Zurück</button><button class="btn primary" type="submit" form="v218MediaMetaForm">Bildtexte speichern</button>`,true);}
  async function uploadMediaInput(input){const files=[...(input.files||[])];if(!files.length)return;const form=input.closest('form');const targetName=input.dataset.targetName||'';const mode=input.dataset.v218Upload||'single';window.stayPilotModal.setBusy(true,files.length>1?'Bilder werden optimiert …':'Bild wird optimiert …');try{const paths=[];for(const file of files){const fd=new FormData();fd.append('image',file);fd.append('seo_name',file.name.replace(/\.[^.]+$/,''));const out=await api('upload_site_media_v218',{method:'POST',formData:fd});paths.push(out.media.file_path);}if(form&&targetName){const target=form.elements.namedItem(targetName);if(target){if(mode==='multiple'){const current=String(target.value||'').trim();target.value=[current,...paths].filter(Boolean).join('\n');}else target.value=paths[paths.length-1];target.dispatchEvent(new Event('input',{bubbles:true}));}}toast(files.length>1?`${files.length} Bilder optimiert und eingefügt.`:'Bild optimiert und eingefügt.');W.data=null;await loadWebsite(true);if(mode==='library')openMediaLibrary();}finally{input.value='';if(window.stayPilotModal.opened)window.stayPilotModal.setBusy(false);}}
  async function saveMediaMeta(form){const f=formDataObject(form),alt_texts={};Object.keys(W.data.languages).forEach(code=>alt_texts[code]=f[`alt_${code}`]||'');const out=await api('save_site_media_meta_v218',{method:'POST',data:{id:Number(f.id),alt_texts}});window.stayPilotModal.markClean();W.data=null;await loadWebsite(true);toast(out.message);openMediaLibrary();}

  function formDataObject(form){const out={};new FormData(form).forEach((v,k)=>out[k]=v);form.querySelectorAll('input[type=checkbox]').forEach(input=>out[input.name]=input.checked?1:0);return out;}
  function parseItems(value){return String(value||'').split(/\r?\n/).map(line=>{const [icon='',title='',...rest]=line.split('|');return{icon:icon.trim()||'✓',title:title.trim(),text:rest.join('|').trim()}}).filter(i=>i.title||i.text);}

  function refreshPageSeoPreviewV236(form){
    if(!form)return;
    const slug=form.elements.slug?.value?.trim()||'seite';
    Object.keys(W.data.languages).forEach(code=>{
      const box=form.querySelector(`[data-v218-page-seo-preview="${code}"]`);if(!box)return;
      const title=form.querySelector(`[name="tr_${code}_title"]`)?.value?.trim()||form.elements.title_fallback?.value?.trim()||'Neue Seite';
      const seoTitle=form.querySelector(`[name="tr_${code}_seo_title"]`)?.value?.trim()||title;
      const seoDesc=form.querySelector(`[name="tr_${code}_seo_description"]`)?.value?.trim()||'Kurze, klickstarke Zusammenfassung dieser Seite für Suchmaschinen und Social-Preview.';
      const urlEl=box.querySelector('.v236-seo-preview-url');
      const titleEl=box.querySelector('.v236-seo-preview-title');
      const descEl=box.querySelector('.v236-seo-preview-desc');
      if(urlEl)urlEl.textContent=`${location.origin}/${slug}`;
      if(titleEl)titleEl.textContent=seoTitle;
      if(descEl)descEl.textContent=seoDesc;
    });
  }

